        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        long[] a = new long[n], queries = new long[m];
        for (int i = 0; i < n; i++) { in.nextToken(); a[i] = (long) in.nval; }
        for (int i = 0; i < m; i++) { in.nextToken(); queries[i] = (long) in.nval; }
        long[] res = closestDifferences(a, queries);
        StringBuilder sb = new StringBuilder();
        for (long v : res) sb.append(v).append('\n');
        System.out.print(sb);
